rule.definition:
if(
  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!username),
  null,
  a!localVariables(
    local!user: #"SYSTEM_SYSRULES_queryEntity_v1"(
      entity: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050377",
      fetchtotalcount: false,
      query: #"SYSTEM_SYSRULES_query"(
        paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: 1
        ),
        logicalexpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
          operator: "AND",
          filters: {
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "userName",
              operator: "=",
              value: ri!username
            ),
            #"SYSTEM_SYSRULES_queryFilter"(
              field: "isActive",
              operator: "=",
              value: true
            )
          }
        )
      )
    ).data,
    if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!user),
      'type!{urn:com:appian:types:CAW}CAW_User'(
        userName: ri!username,
        firstName: ri!firstName,
        lastName: ri!lastName,
        createdBy: "System",
        createdOn: now(),
        modifiedBy: "System",
        modifiedOn: now(),
        isActive: true
      ),
      local!user
    )
  )
)
